import re

with open('doc/superhero.md', 'r') as f:
    content = f.read()

lines = content.split('\n')

# Extract all biometric data
biometric_data = {}
for i, line in enumerate(lines):
    id_match = re.search(r'ID\s+(\d+)', line)
    if not id_match:
        id_match = re.search(r'identifier\s+(\d+)', line)
    if not id_match:
        id_match = re.search(r'(?:registry number|reference code)\s+(\d+)', line, re.IGNORECASE)

    if id_match:
        hero_id = id_match.group(1)
        height_match = re.search(r'[Hh]eight.*?(\d+\.\d+)\s*centimeters', line)
        if height_match:
            height = float(height_match.group(1))
            biometric_data[hero_id] = height

# Extract all publisher data
publisher_data = {}
for i, line in enumerate(lines):
    if 'publisher' in line.lower():
        id_match = re.search(r'ID\s+(\d+)', line)
        if not id_match:
            id_match = re.search(r'identifier\s+(\d+)', line)
        if not id_match:
            id_match = re.search(r'(?:registry number|reference code)\s+(\d+)', line, re.IGNORECASE)

        if id_match:
            hero_id = id_match.group(1)
            pub_match = re.search(r'[Pp]ublisher.*?([0-9]+)', line)
            if pub_match:
                publisher_data[hero_id] = pub_match.group(1)

print(f"Biometric entries: {len(biometric_data)}")
print(f"Publisher entries: {len(publisher_data)}")

# Join data and filter for height between 150-180
heroes_in_range = []
for hero_id, height in biometric_data.items():
    if 150 <= height <= 180:
        pub_id = publisher_data.get(hero_id)
        heroes_in_range.append((hero_id, height, pub_id))

print(f"\nHeroes with height 150-180: {len(heroes_in_range)}")
for h in heroes_in_range:
    print(f"ID {h[0]}: height {h[1]}, publisher_id {h[2]}")

# Calculate percentage of Marvel Comics (publisher_id 13)
marvel_count = sum(1 for h in heroes_in_range if h[2] == '13')
total = len(heroes_in_range)
percentage = (marvel_count / total * 100) if total > 0 else 0

print(f"\nTotal heroes in height range 150-180: {total}")
print(f"Marvel Comics (publisher_id 13): {marvel_count}")
print(f"Percentage: {percentage:.2f}%")

